mapper.select:
SELECT id, blog_id, author_type, author_id, content, parent_comment_id, created_at, updated_at
FROM blog_comments
WHERE id = #{id}

SELECT COUNT(*)
FROM blog_comments
WHERE blog_id = #{blogId}

mapper.update:
UPDATE blog_comments
SET content = #{content}
WHERE id = #{id}

mapper.delete:
WITH RECURSIVE descendants AS (
    SELECT id FROM blog_comments WHERE id = #{id}
    UNION ALL
    SELECT c.id FROM blog_comments c INNER JOIN descendants d ON c.parent_comment_id = d.id
)
DELETE FROM blog_comments WHERE id IN (SELECT id FROM descendants)
